package com.codeguardian.service; import org.springframework.stereotype.Service; import java.io.IOException; import java.nio.file.*; import java.util.*; import java.util.concurrent.*; import java.util.stream.*;
@Service public class CodeParserService{private static final Set<String> EXT=Set.of(".java",".py",".js",".ts",".jsx",".tsx",".go",".rs",".cpp",".c",".cs");public List<Path> scanDirectory(String path){try(Stream<Path>s=Files.walk(Path.of(path))){return s.filter(Files::isRegularFile).filter(this::source).toList();}catch(IOException e){throw new IllegalArgumentException("Cannot scan directory: "+path,e);}}public Map<String,String> readDirectoryParallel(String path){try(var executor=Executors.newVirtualThreadPerTaskExecutor()){return scanDirectory(path).stream().map(p->CompletableFuture.supplyAsync(()->Map.entry(p.toString(),read(p)),executor)).map(CompletableFuture::join).collect(Collectors.toMap(Map.Entry::getKey,Map.Entry::getValue));}}private boolean source(Path p){String n=p.toString().toLowerCase();return EXT.stream().anyMatch(n::endsWith);}private String read(Path p){try{return Files.readString(p);}catch(IOException e){throw new CompletionException(e);}}}
